import os
import sys
import fire
import fitz

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _convert_to_image(pdf_file_path, image_file_path):
    try:
        with fitz.open(pdf_file_path) as doc:
            page = doc.load_page(0)
            pix = page.get_pixmap()
            pix.save(image_file_path)
        return True
    except Exception:
        return False


@log_tool_call("pdf.convert_to_image")
def main(pdf_file_path, image_file_path):
    if not os.path.exists(pdf_file_path):
        return f"OBSERVATION: The file {pdf_file_path} does not exist. Failed to convert pdf to image."
    success = _convert_to_image(pdf_file_path, image_file_path)
    if success:
        return f"OBSERVATION: Successfully convert {pdf_file_path} to {image_file_path}"
    return f"OBSERVATION: Failed to convert {pdf_file_path} to {image_file_path}"


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import pytesseract
from PIL import Image

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _recognize_file(file_path):
    try:
        return pytesseract.image_to_string(Image.open(file_path))
    except Exception:
        return None


@log_tool_call("ocr.recognize_file")
def main(file_path):
    if not os.path.exists(file_path):
        return f"OBSERVATION: The file {file_path} does not exist. Failed to recognize text."
    text = _recognize_file(file_path)
    if text:
        return f"OBSERVATION: The text from {file_path} is:\n{text}"
    return f"OBSERVATION: Failed to recognize text from {file_path}"


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import openpyxl

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _create_new_file(file_path):
    try:
        os.makedirs(os.path.dirname(file_path), exist_ok=True)
        wb = openpyxl.Workbook()
        wb.active.title = "Sheet"
        wb.save(file_path)
        return True
    except Exception:
        return False


@log_tool_call("excel.create_new_file")
def main(file_path):
    if os.path.exists(file_path):
        return f"OBSERVATION: File {file_path} already exists"
    success = _create_new_file(file_path)
    if success:
        return f"OBSERVATION: Successfully create new file {file_path}"
    return f"OBSERVATION: Failed to create new file {file_path}"


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import openpyxl

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _set_cell(file_path, text, row_idx, column_idx, sheet_name=None):
    if text is True:
        text = ""
    try:
        workbook = openpyxl.load_workbook(file_path) if os.path.exists(file_path) else openpyxl.Workbook()
        if sheet_name is None:
            sheet = workbook.active
        else:
            try:
                sheet = workbook[sheet_name]
            except KeyError:
                sheet = workbook.create_sheet(title=sheet_name)
        sheet.cell(row=int(row_idx), column=int(column_idx), value=text)
        workbook.save(file_path)
        return True
    except Exception:
        return False


@log_tool_call("excel.set_cell")
def main(file_path, row_idx, column_idx, text, sheet_name=None):
    if not os.path.exists(file_path):
        return f"OBSERVATION: The file {file_path} does not exist. Failed to write to the file."
    success = _set_cell(file_path, text, row_idx, column_idx, sheet_name)
    if success:
        return f"OBSERVATION: Successfully write text to {file_path}"
    return f"OBSERVATION: Failed to write text to {file_path}"


if __name__ == "__main__":
    fire.Fire(main)
